let selectedDay=0, taskFilter='active', taskQuery='', expanded=new Set(), sidebarOpen=false, modalCleanup=null;
let cloud=null, syncMessage='', syncBusy=false, pendingRemote=false, hemis=null, installPrompt=null, notificationRegistration=null, saveError=false;
let beforeModalFocus=null, toastTimer;
let connectionConfig=getConnectionSettings(),connectionKey='';

function toast(message) { const el=document.querySelector('#toast'); el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),4800); }
function save(message='') {
  state.updatedAt=new Date().toISOString();
  state=validateState(state);
  try {localStorage.setItem(STORE,JSON.stringify(state));saveError=false;}catch{saveError=true;toast('Не удалось сохранить в браузере. Экспортируйте JSON-копию.');}
  render(); if(message)toast(message);
}
function navigate(next) { route=next;sidebarOpen=false;location.hash=next;render();window.scrollTo({top:0}); }
function weekDates() {
 const today=dateInfo();const d=new Date(`${today.date}T12:00:00Z`);d.setUTCDate(d.getUTCDate()-(today.day-1));
 return Array.from({length:7},(_,i)=>{const date=new Date(d);date.setUTCDate(d.getUTCDate()+i);return date.toISOString().slice(0,10);});
}
function badge(subject) {
 const s=attendanceStats(subject);return `<button class="badge ${s.status}" data-action="attendance-edit" data-id="${esc(subject?.id)}" title="${s.percent===null?'Укажите часы предмета':`${fmt(s.missed)} ч НБ · ${fmt(s.percent)}% от часов предмета`}"><span class="mono">НБ ${fmt(s.missed)}</span>${s.status==='critical'?' !':''}</button>`;
}
function render() {
 const resolvedTheme=applyTheme(state.settings.theme);
 const active=state.tasks.filter(t=>!t.done).length;
 const nav=(id,name,glyph,count='')=>`<button data-nav="${id}" class="${route===id?'active':''}" ${route===id?'aria-current="page"':''}>${icon(glyph)}<span>${name}</span>${count!==''?`<span class="count">${count}</span>`:''}</button>`;
 const title={schedule:'Расписание',tasks:'Задания',attendance:'Посещаемость',sync:'Синхронизация',settings:'Настройки',connection:'Подключение HEMIS'}[route];
 const initials=(state.profile.name||'Мой профиль').split(' ').slice(0,2).map(s=>s[0]).join('');
 app.innerHTML=`<div class="layout"><div class="mobile-backdrop ${sidebarOpen?'visible':''}" data-action="menu-close"></div><aside class="sidebar ${sidebarOpen?'open':''}" aria-label="Главное меню"><a class="brand" href="#schedule"><span class="brand-mark">H</span><span class="brand-name">HEMIS <span>Planner</span></span></a><p class="workspace-label">Моё пространство</p><nav class="nav">${nav('schedule','Расписание','calendar')}${nav('tasks','Задания','tasks',active)}${nav('attendance','Посещаемость','chart')}<div class="nav-divider"></div>${nav('connection','Подключить HEMIS','link')}${nav('sync','Синхронизация','cloud')}</nav><div class="nav-bottom"><div class="sidebar-tip"><p>Учёба под контролем.<br>Одна неделя за раз.</p><button data-action="install">Установить приложение ${icon('arrow')}</button></div><nav class="nav">${nav('settings','Настройки','settings')}<button data-action="search">${icon('search')}<span>Быстрый поиск</span><kbd class="key-hint" style="margin-left:auto">⌘ K</kbd></button></nav><div class="profile"><div class="avatar">${esc(initials)}</div><div><div class="profile-name">${esc(state.profile.name||'Мой профиль')}</div><small>${esc(state.profile.university||'Локальное пространство')}</small></div></div></div></aside><div class="main-shell">${navigator.onLine?'':'<div class="offline-banner">Вы офлайн · расписание и задания доступны на этом устройстве</div>'}<header class="topbar"><div class="breadcrumb"><button class="icon-btn menu-toggle" data-action="menu" aria-label="Открыть меню">${icon('menu')}</button><span>Моё пространство</span>${icon('chevron')}<strong>${title}</strong></div><div class="top-actions"><span class="saved"><i></i>${saveError?'Ошибка сохранения':'Сохранено на устройстве'}</span>${state.mode==='demo'?'<span class="badge demo mode-badge">Демо-режим</span>':''}<button class="icon-btn" data-action="theme-toggle" title="Сменить тему" aria-label="${resolvedTheme==='dark'?'Включить светлую тему':'Включить тёмную тему'}">${icon(resolvedTheme==='dark'?'sun':'moon')}</button><button class="icon-btn" data-action="search" title="Поиск (Ctrl+K)" aria-label="Поиск">${icon('search')}</button><button class="icon-btn" data-nav="settings" title="Уведомления" aria-label="Настройки уведомлений">${icon('bell')}</button></div></header><main id="main" class="content" tabindex="-1">${renderPage()}</main></div></div>`;
}
function heading(title,subtitle,buttons='') {
 return `<div class="page-eyebrow">ЛИЧНЫЙ ПЛАНИРОВЩИК <span class="dot"></span> ${state.mode==='demo'?'ДЕМОНСТРАЦИОННЫЕ ДАННЫЕ':esc(state.profile.university||'HEMIS PLANNER')}</div><div class="page-heading"><div><h1>${title}</h1><p>${subtitle}</p></div><div class="actions">${buttons}</div></div>`;
}
const newTaskButton=()=>`<button class="btn primary" data-action="task-new">${icon('plus')} Новое задание</button>`;
function renderPage() {
 if(route==='schedule')return renderSchedule();
 if(route==='tasks')return renderTasks();
 if(route==='attendance')return renderAttendance();
 if(route==='sync')return renderSync();
 if(route==='settings')return renderSettings();
 return renderConnection();
}
function liveWidget(){
 const live=dayStatus(state.schedule), now=dateInfo();let label,title,caption,minutes='',progress=0;
 if(live.kind==='live'){label='Сейчас идёт пара';title=live.current.subject;caption=`Ауд. ${live.current.room} · до ${live.current.end}`;minutes=`${live.minutes} <small>мин осталось</small>`;progress=live.progress;}
 else if(live.kind==='break'||live.kind==='upcoming'){label=live.kind==='break'?'Время на перерыв':'До начала занятий';title=live.next.subject;caption=`Следующая пара · ${live.next.start} · ауд. ${live.next.room}`;minutes=`${live.minutes} <small>мин до пары</small>`;}
 else{label=live.kind==='done'?'На сегодня всё':'Сегодня без пар';title=live.kind==='done'?'Можно выдохнуть.':'Время для своих планов.';caption='Загляните в задания и подготовьтесь к завтра';minutes=icon('sun');progress=live.kind==='done'?100:0;}
 return `<section class="live-card" aria-label="Статус учебного дня"><div class="live-header"><span class="live-label"><i></i>${label}</span><span class="mono">${now.time} · UZT</span></div><div class="live-title"><h2>${esc(title)}</h2><span class="mono">${minutes}</span></div><div class="live-caption"><span>${esc(caption)}</span>${live.kind==='live'?`<span class="mono">${Math.round(progress)}%</span>`:''}</div><div class="progress" role="progressbar" aria-label="Ход текущей пары" aria-valuenow="${Math.round(progress)}" aria-valuemin="0" aria-valuemax="100"><span style="width:${progress}%"></span></div></section>`;
}
function renderSchedule(){
 const summary=summaries(state),dates=weekDates(),today=dateInfo();
 const active=state.tasks.filter(t=>!t.done).length;
 const days=selectedDay?[selectedDay]:[1,2,3,4,5,6];
 return heading('Моя учебная неделя','Расписание, задания и немного спокойствия.',`<button class="btn" data-action="lesson-new">${icon('plus')} Добавить пару</button>${newTaskButton()}`)+`<div class="dashboard-grid"><div class="primary-column">${liveWidget()}<div class="summary-strip"><div class="summary-cell"><label>Сегодня, ${dateLabel(today.date)}</label><strong>${summary.today.lessons}</strong><small>${plural(summary.today.lessons,['пара','пары','пар'])}</small><p class="minor">${taskText(summary.today.tasks)} к сдаче</p></div><div class="summary-cell"><label>Завтра, ${dateLabel(tomorrowDate())}</label><strong>${summary.tomorrow.lessons}</strong><small>${plural(summary.tomorrow.lessons,['пара','пары','пар'])}</small><p class="minor">${taskText(summary.tomorrow.tasks)} к сдаче</p></div><div class="summary-cell"><label>В работе</label><strong>${active.toString().padStart(2,'0')}</strong><small>${plural(active,['задание','задания','заданий'])}</small><p class="minor">${state.subjects.length} предметов в семестре</p></div></div><div class="section-toolbar"><h2>${icon('calendar')} Расписание</h2><span class="subtle">${dateLabel(dates[0])} — ${dateLabel(dates[5])} <span class="desktop-only">· каждую неделю</span></span></div><div class="day-tabs" role="group" aria-label="Фильтр дней недели"><button class="day-tab ${!selectedDay?'selected':''}" data-day="0" aria-pressed="${!selectedDay}">Все дни</button>${[1,2,3,4,5,6].map(d=>`<button class="day-tab ${selectedDay===d?'selected':''} ${today.day===d?'is-today':''}" data-day="${d}" aria-pressed="${selectedDay===d}" title="${DAYS[d]}${today.day===d?' · сегодня':''}">${SHORT_DAYS[d]}</button>`).join('')}</div>${days.map(day=>renderDay(day,dates[day-1],today.day)).join('')}<div class="page-foot"><span>${state.mode==='demo'?'Демо-данные · подключите свой вуз для начала':'Еженедельное расписание · время Ташкента (UTC+5)'}</span><button class="text-btn" data-action="lesson-new">${icon('plus')} Добавить пару</button></div></div>${renderAside(dates)}</div>`;
}
function renderDay(day,date,today){
 const lessons=state.schedule.filter(l=>l.day===day).sort((a,b)=>a.start.localeCompare(b.start));
 return `<section class="day-section" aria-label="${DAYS[day]}"><div class="day-title"><h3>${DAYS[day]}</h3><span class="date">${dateLabel(date)}</span>${day===today?'<span class="today-tag">Сегодня</span>':''}<span class="pair-count">${pairText(lessons.length)}</span></div>${lessons.length?lessons.map(renderLesson).join(''):`<div class="empty"><strong>Здесь пока свободно</strong>Добавьте пару или подключите расписание HEMIS.<br><button class="btn" data-action="lesson-new" data-day="${day}">${icon('plus')} Добавить пару</button></div>`}</section>`;
}
function renderLesson(lesson){
 const isLive=dayStatus(state.schedule).current?.id===lesson.id;
 const tasks=state.tasks.filter(t=>t.subjectId===lesson.subjectId&&t.day===lesson.day).sort((a,b)=>Number(a.done)-Number(b.done));
 return `<article class="lesson ${isLive?'is-live':''}"><div class="lesson-time"><time>${lesson.start}</time><time>${lesson.end}</time></div><div class="lesson-content"><div class="lesson-head"><h4 class="lesson-name">${esc(lesson.subject)}</h4><div class="lesson-head-actions">${badge(subjectFor(lesson.subjectId))}<button class="icon-btn" data-action="lesson-edit" data-id="${esc(lesson.id)}" aria-label="Изменить пару ${esc(lesson.subject)}">${icon('edit')}</button></div></div><div class="lesson-meta"><span class="lesson-type">${esc(lesson.type)}</span><span class="separator"></span><span>${icon('pin')} ${esc(lesson.room)}</span><span class="separator"></span><span>${esc(lesson.teacher)}</span></div>${tasks.length?`<div class="task-list">${tasks.map(task=>renderTask(task,lesson.id)).join('')}</div>`:''}<button class="quick-add" data-action="task-new" data-subject="${esc(lesson.subjectId)}" data-day="${lesson.day}">${icon('plus')} Задание</button></div></article>`;
}
function renderTask(task,context='list'){
 const completed=task.checklist.filter(c=>c.done).length,total=task.checklist.length;
 const open=expanded.has(task.id),overdue=!task.done&&task.due&&task.due<localDate();
 const checkboxId=`task-${task.id}-${context}`;
 return `<div class="task ${task.done?'completed':''}"><div class="task-main"><input class="check" type="checkbox" id="${esc(checkboxId)}" data-task-toggle="${esc(task.id)}" ${task.done?'checked':''} aria-label="Выполнено: ${esc(task.title)}"><button class="task-title" data-action="task-expand" data-id="${esc(task.id)}" aria-expanded="${open}">${esc(task.title)}</button><span class="priority-dot ${task.priority}" title="Приоритет: ${{high:'высокий',medium:'средний',low:'низкий'}[task.priority]}"></span>${task.due?`<time class="task-due ${overdue?'overdue':''}" datetime="${task.due}">${dateLabel(task.due,{day:'2-digit',month:'2-digit'})}</time>`:''}</div><div class="task-subline"><span>${esc(task.type)}</span>${total?`${icon('tasks')}<span class="mono">${completed}/${total}</span><span class="mini-progress"><span style="width:${completed/total*100}%"></span></span>`:''}${task.url?`<a href="${esc(task.url)}" target="_blank" rel="noopener noreferrer">${icon('link')} Материалы</a>`:''}${context==='list'?`<span>· ${SHORT_DAYS[task.day]}</span>`:''}</div>${open?`<div class="task-details">${task.notes?`<p>${esc(task.notes)}</p>`:''}${total?`<div class="checklist">${task.checklist.map(step=>`<label><input class="check" type="checkbox" data-step-toggle="${esc(step.id)}" data-task="${esc(task.id)}" ${step.done?'checked':''}>${esc(step.text)}</label>`).join('')}</div>`:''}<div class="task-edit-actions"><button class="text-btn" data-action="task-edit" data-id="${esc(task.id)}">${icon('edit')} Изменить</button><button class="text-btn delete" data-action="task-delete" data-id="${esc(task.id)}">${icon('trash')} Удалить</button></div></div>`:''}</div>`;
}
function renderAside(dates){
 const done=state.tasks.filter(t=>t.done).length,total=state.tasks.length,percent=total?Math.round(done/total*100):0;
 const deadlines=state.tasks.filter(t=>!t.done&&t.due).sort((a,b)=>a.due.localeCompare(b.due)).slice(0,3);
 const month=dateLabel(dates[0],{month:'long',year:'numeric'});
 const now=dateInfo();const first=dates[0].slice(0,8)+'01';const offset=dateInfo(new Date(`${first}T12:00:00+05:00`)).day-1;
 const monthDays=new Date(Number(first.slice(0,4)),Number(first.slice(5,7)),0).getDate();
 return `<aside class="aside" aria-label="Сводка недели"><section class="aside-section"><h3 class="aside-title">Маленькие шаги, большой прогресс ${icon('chart')}</h3><div class="weekly-progress"><div class="ring"><svg viewBox="0 0 70 70" aria-hidden="true"><circle class="ring-bg" cx="35" cy="35" r="30"/><circle class="ring-value" cx="35" cy="35" r="30" stroke-dasharray="${percent*1.885} 188.5"/></svg><strong>${percent}%</strong></div><div class="weekly-copy"><strong>${done} из ${total} выполнено</strong><p>Каждое закрытое задание —<br>чуть меньше забот.</p></div></div><p class="aside-caption">Отмечайте готовые задания и подзадачи.<br>Остальное уже на своих местах.</p></section><section class="aside-section"><h3 class="aside-title">Ближайшие дедлайны ${icon('clock')}</h3><div class="deadline-list">${deadlines.map(t=>`<div class="deadline"><div class="deadline-icon">${icon(t.type===TASK_TYPES[1]?'file':'tasks')}</div><div><button data-action="task-edit" data-id="${esc(t.id)}">${esc(t.title)}</button><p><span>${esc(subjectFor(t.subjectId)?.name)}</span><time>${dateLabel(t.due,{day:'2-digit',month:'2-digit'})}</time></p></div></div>`).join('')||'<p class="aside-note">Дедлайнов пока нет. Хороший момент, чтобы спланировать неделю.</p>'}</div></section><section class="aside-section calendar-section"><h3 class="aside-title" style="text-transform:capitalize">${month} ${icon('calendar')}</h3><div class="mini-calendar">${[1,2,3,4,5,6,7].map(d=>`<span>${SHORT_DAYS[d]}</span>`).join('')}${'<span></span>'.repeat(offset)}${Array.from({length:monthDays},(_,i)=>`<span class="cal-day ${first.slice(0,8)+(i+1).toString().padStart(2,'0')===now.date?'current':''}">${i+1}</span>`).join('')}</div><p class="aside-note">${icon('info')} <strong>Всё по местному времени.</strong><br>Ваш учебный день — в часовом поясе Ташкента.</p></section><div class="sync-mini">${icon(cloud?'lock':'cloud')}<div><h4>${cloud?'Защищённая синхронизация':'С собой на любом устройстве'}</h4><p>${cloud?'Отправляйте изменения в облако и открывайте на телефоне.':'Подключите зашифрованный перенос между ноутбуком и телефоном.'}</p><button data-nav="sync">${cloud?'Открыть синхронизацию':'Настроить синхронизацию'} ${icon('arrow')}</button></div></div><p class="footer-note"><span>HEMIS PLANNER</span><br>Меньше хаоса. Больше пространства для важного.</p></aside>`;
}
function renderTasks(){
 let tasks=state.tasks.filter(t=>(taskFilter==='all'||(taskFilter==='done'?t.done:taskFilter==='overdue'?!t.done&&t.due&&t.due<localDate():!t.done))&&(!taskQuery||`${t.title} ${subjectFor(t.subjectId)?.name} ${t.notes}`.toLowerCase().includes(taskQuery.toLowerCase())));
 return heading('Задания без хаоса','От первого пункта до последней галочки.',newTaskButton())+`<div class="view-body"><div class="view-tools"><label class="search-field">${icon('search')}<input id="task-search" class="input" type="search" placeholder="Найти задание…" value="${esc(taskQuery)}" aria-label="Поиск заданий"></label><select class="input filter-select" id="task-filter" aria-label="Статус заданий">${[['active','В работе'],['all','Все задания'],['done','Выполненные'],['overdue','Просроченные']].map(([v,n])=>`<option value="${v}" ${taskFilter===v?'selected':''}>${n}</option>`).join('')}</select></div><div class="full-task-list">${tasks.length?state.subjects.map(s=>{const group=tasks.filter(t=>t.subjectId===s.id).sort((a,b)=>(a.due||'9999').localeCompare(b.due||'9999'));return group.length?`<section class="full-task-group"><h3>${esc(s.name)}<span>${taskText(group.length)}</span></h3>${group.map(t=>renderTask(t)).join('')}</section>`:'';}).join(''):`<div class="empty">${icon('check')}<strong>Здесь пока спокойно</strong>Заданий по выбранному фильтру нет.<br><button class="btn" data-action="task-new">${icon('plus')} Добавить задание</button></div>`}</div></div>`;
}
function renderAttendance(){
 const stats=state.subjects.map(attendanceStats),critical=stats.filter(s=>s.status==='critical').length,warning=stats.filter(s=>s.status==='warning').length;
 return heading('Посещаемость под контролем','НБ по каждому предмету — чтобы видеть запас заранее.',`<button class="btn" data-action="hemis-refresh">${icon('refresh')} Обновить из HEMIS</button>`)+`<div class="view-body"><div class="attendance-overview"><div><strong>${state.subjects.length.toString().padStart(2,'0')}</strong><p>предметов в семестре</p></div><div><strong style="color:var(--amber)">${warning.toString().padStart(2,'0')}</strong><p>требуют внимания · от 15%</p></div><div><strong style="color:var(--red)">${critical.toString().padStart(2,'0')}</strong><p>в зоне риска · от 20%</p></div></div><div class="attendance-grid">${state.subjects.map(s=>{const a=attendanceStats(s),active=state.tasks.filter(t=>t.subjectId===s.id&&!t.done).length;return `<article class="attendance-card ${a.status}"><header><h3>${esc(s.name)}</h3>${badge(s)}</header><div class="attendance-percentage"><strong>${a.percent===null?'—':fmt(a.percent)+'<small>%</small>'}</strong><small>порог <span class="mono">25%</span> · ${a.total===null?'часы не указаны':`${fmt(a.total)} ч всего`}</small></div><div class="progress" role="progressbar" aria-label="Использовано порога НБ по ${esc(s.name)}" aria-valuenow="${a.percent===null?0:Math.min(100,Math.round(a.percent/25*100))}" aria-valuemin="0" aria-valuemax="100"><span style="width:${a.percent===null?0:Math.min(100,a.percent/25*100)}%"></span></div><div class="absence-split"><div>Уважительные<b>${fmt(a.excused)} ч</b></div><div>Неуважительные<b>${fmt(a.unexcused)} ч</b></div></div><footer><span>${a.total===null?'Укажите часы для расчёта':a.percent>=25?'Порог 25% достигнут':`До порога: ${fmt(a.remainingHours)} ч`}</span><span>${taskText(active)} в работе</span><button class="icon-btn" data-action="attendance-edit" data-id="${esc(s.id)}" aria-label="Изменить посещаемость ${esc(s.name)}">${icon('edit')}</button></footer></article>`;}).join('')||'<div class="empty"><strong>Предметы ещё не добавлены</strong>Подключите HEMIS или добавьте пару вручную.</div>'}</div><div class="info-note">${icon('info')}<span>Индикатор считает все пропущенные часы, включая уважительные, от общего числа часов предмета. Зелёный — менее 15%, жёлтый — от 15%, красный — от 20%; при 25% порог достигнут. Это плановый ориентир: часы и правила допуска сверяйте с вашим вузом. Нажмите НБ, чтобы уточнить исходные данные.</span></div></div>`;
}
function renderConnection(){
 return heading('Ваш вуз. Ваше расписание.','Подключите студенческий портал или начните самостоятельно.')+`<div class="view-body"><section class="connection-card"><h3>${icon('link')} Подключение к HEMIS</h3><p>Расписание, предметы и посещаемость из вашего личного кабинета. Логин, пароль и Bearer-токен используются только в текущем сеансе и не попадают в резервные копии.</p><button class="btn primary" data-action="connect">${icon('link')} Подключить мой вуз</button>${hemis?'<button class="btn" data-action="hemis-refresh" style="margin-left:8px">Обновить данные</button>':''}</section><section class="connection-card"><h3>Вход с GitHub и телефона</h3><p>Для входа в HEMIS при ограничениях CORS нужен отдельно опубликованный HTTPS-мост. Одной загрузки файлов на GitHub недостаточно. Инструкция поможет создать собственный сервер через браузер.</p><a class="btn" href="./bridge-setup.html" target="_blank" rel="noopener noreferrer">Настроить HTTPS-мост ${icon('arrow')}</a></section><section class="connection-card"><h3>Уже есть ответ API?</h3><p>Импортируйте сырой JSON расписания или объект с полями schedule, subjects и attendance. Недостающие часы предметов можно указать вручную.</p><button class="btn" data-action="raw-import">${icon('file')} Вставить JSON</button></section><section class="connection-card"><h3>Сначала посмотреть, как всё устроено</h3><p>Демо-расписание, семь заданий с чек-листами и примеры посещаемости. Или начните с чистого листа и добавьте свои пары.</p><button class="btn" data-action="demo">Открыть демо</button><button class="btn ghost" data-action="empty">Чистое пространство ${icon('arrow')}</button></section><div class="info-note" style="max-width:680px">${icon('info')}<span>На Windows запустите start.bat из папки приложения: откроется локальная версия с мостом HEMIS. Для размещённого сайта мост должен быть запущен на том же компьютере. Мост использует ваш IP и не снимает Geo-IP-ограничения вуза; настройки браузера также могут ограничивать доступ к localhost.</span></div></div>`;
}
function renderSync(){
 return heading('Ноутбук ↔ телефон','Одна учебная неделя на двух устройствах.')+`<div class="view-body"><section class="settings-card"><h2>${icon('lock')} Данные под вашим ключом</h2><p>Введите одинаковый ID студента и отдельный пароль синхронизации на обоих устройствах. Данные шифруются в браузере перед отправкой.</p>${cloud?`<div class="sync-state">${icon('check')} Ключ создан · сеанс открыт до закрытия приложения</div><div class="settings-inline"><button class="btn primary" data-action="sync-push" ${syncBusy?'disabled':''}>${icon('upload')} Отправить в облако</button><button class="btn" data-action="sync-pull" ${syncBusy?'disabled':''}>${icon('download')} Загрузить из облака</button><button class="btn ghost" data-action="sync-disconnect" ${syncBusy?'disabled':''}>Завершить сеанс</button></div>`:`<form id="sync-form"><div class="form-grid"><label class="field">ID студента<input class="input" name="studentId" required autocomplete="off" maxlength="160" placeholder="Например, 123456789"></label><label class="field">Пароль синхронизации<input class="input" name="password" type="password" required minlength="10" maxlength="256" autocomplete="new-password" placeholder="Не менее 10 символов"></label></div><div class="form-actions"><button class="btn primary" type="submit">${icon('lock')} Создать защищённый сеанс</button></div></form>`}<p id="sync-status" class="form-status" role="status">${esc(syncMessage)}</p><div class="notice">${esc(SYNC_INFO.retention)}<br>Сначала загрузите существующую облачную копию. Отправка и загрузка выполняются кнопками; изменения на устройстве сохраняются сразу. При одновременной работе экспортируйте локальную копию до загрузки чужих изменений. Пароль не восстанавливается.</div></section><section class="settings-card"><h2>Резервная копия, которая остаётся у вас</h2><p>Расписание, задания, чек-листы и статистика НБ в одном JSON-файле. В копии нет паролей HEMIS, токенов или ключа синхронизации. Сам JSON-файл не зашифрован.</p><div class="settings-inline"><button class="btn" data-action="export">${icon('download')} Экспорт .json</button><button class="btn" data-action="backup-import">${icon('upload')} Импорт .json</button></div></section><div class="info-note" style="max-width:760px">${icon('info')}<span>Сервис переноса — ntfy.sh. Шифрование AES-GCM, ключ из ID и пароля через PBKDF2 / SHA-256. Канал определяется этими же данными, отдельный токен или регистрация не нужны. Бесплатный сервис ограничивает размер и частоту отправок; для больших архивов используйте JSON.</span></div></div>`;
}
function renderAppearance(){
 return `<section class="settings-card"><h2>Тема оформления</h2><p>Выберите удобное оформление. Режим «Как на устройстве» следует светлой или тёмной теме системы.</p><label class="field" style="max-width:320px">Оформление<select class="input" id="theme-select">${THEMES.map(theme=>`<option value="${theme.id}" ${state.settings.theme===theme.id?'selected':''}>${theme.name}</option>`).join('')}</select></label><p class="appearance-caption">Выбор сохраняется автоматически.</p></section>`;
}
function renderSettings(){
 return heading('Всё по-вашему','Профиль, спокойные напоминания и ваши данные.')+`<div class="view-body">${renderAppearance()}<form id="profile-form" class="settings-card"><h2>Моё пространство</h2><p>Эти данные видны только в вашем планировщике.</p><div class="form-grid"><label class="field">Имя<input name="name" class="input" maxlength="120" value="${esc(state.profile.name)}" placeholder="Как к вам обращаться"></label><label class="field">Вуз<input name="university" class="input" maxlength="160" value="${esc(state.profile.university)}" placeholder="Название университета"></label><label class="field">Группа<input name="group" class="input" maxlength="80" value="${esc(state.profile.group)}" placeholder="CS–23"></label><label class="field">Часовой пояс<input class="input" value="Ташкент · UTC+5" disabled></label></div><div class="form-actions"><button class="btn primary" type="submit">Сохранить профиль</button></div></form><form id="notification-form" class="settings-card"><h2>Завтра начинается сегодня</h2><p>Вечернее уведомление напомнит, сколько завтра пар и какие задания нужно сдать. Работает при открытом приложении; доставка в фоне зависит от браузера. Закрытое приложение не может запускать таймер без push-сервера.</p><div class="settings-inline"><label class="checkbox-label"><input type="checkbox" name="enabled" ${state.settings.notificationEnabled?'checked':''}>Вечернее напоминание</label><label class="field">Время (Ташкент)<input class="input" type="time" name="time" value="${state.settings.notificationTime}" required></label></div><div class="form-actions"><button class="btn" data-action="notification-test" type="button">Проверить уведомление</button><button class="btn primary" type="submit">Сохранить</button></div></form><section class="settings-card"><h2>Приложение на вашем устройстве</h2><p>После первого открытия по HTTPS или localhost расписание и задания доступны офлайн. Добавьте Planner на экран «Домой» для быстрого доступа.</p><div class="settings-inline"><button class="btn" data-action="install">${icon('download')} Установить PWA</button><button class="btn" data-action="export">Экспорт данных</button></div></section></div>`;
}

function closeModal(){
 if(modalCleanup)modalCleanup();modalCleanup=null;modalRoot.innerHTML='';document.body.style.overflow='';
 beforeModalFocus?.focus?.();beforeModalFocus=null;
}
function modal(title,html,{wide=false,onSubmit}={}){
 if(modalRoot.firstChild)closeModal();beforeModalFocus=document.activeElement;
 modalRoot.innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><header class="modal-header"><h2 id="dialog-title">${title}</h2><button class="icon-btn" data-action="modal-close" aria-label="Закрыть">${icon('close')}</button></header><div class="modal-body">${html}</div></section></div>`;document.body.style.overflow='hidden';
 const dialog=modalRoot.querySelector('.modal');
 const keyHandler=e=>{if(e.key==='Escape'){closeModal();return;}if(e.key==='Tab'){const nodes=[...dialog.querySelectorAll('button:not(:disabled),a,input:not(:disabled),select,textarea,[tabindex="0"]')].filter(n=>n.getClientRects().length);if(!nodes.length)return;const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}};
 document.addEventListener('keydown',keyHandler);modalCleanup=()=>document.removeEventListener('keydown',keyHandler);
 const backdrop=modalRoot.querySelector('.modal-backdrop');let backdropPress=false;
 backdrop.addEventListener('pointerdown',e=>{backdropPress=e.target===backdrop;});
 backdrop.addEventListener('click',e=>{if((!e.detail||backdropPress)&&e.target===backdrop)closeModal();backdropPress=false;});
 if(onSubmit)dialog.querySelector('form')?.addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget;const status=form.querySelector('.form-status');try{await onSubmit(form);}catch(error){if(status){status.textContent=error.message;status.classList.add('error');}else toast(error.message);}});
 setTimeout(()=>(dialog.querySelector('input:not([type="checkbox"]),select,textarea')||dialog.querySelector('button'))?.focus(),30);
}
function confirmDialog(title,description,onConfirm,button='Продолжить'){
 modal(esc(title),`<p class="modal-description">${esc(description)}</p><div class="form-actions"><button class="btn" data-action="modal-close">Отмена</button><button class="btn primary" id="confirm-action">${esc(button)}</button></div>`);
 modalRoot.querySelector('#confirm-action').onclick=()=>{closeModal();onConfirm();};
}
function dayOptions(day){return [1,2,3,4,5,6].map(d=>`<option value="${d}" ${Number(day)===d?'selected':''}>${DAYS[d]}</option>`).join('');}
function subjectOptions(id){return state.subjects.map(s=>`<option value="${esc(s.id)}" ${s.id===id?'selected':''}>${esc(s.name)}</option>`).join('');}
function taskEditor(id='',subjectId='',day=0){
 if(!state.subjects.length){toast('Сначала добавьте предмет через «Добавить пару».');lessonEditor();return;}
 const old=state.tasks.find(t=>t.id===id);
 const t=old||{title:'',subjectId:subjectId||state.subjects[0].id,day:Number(day)||(selectedDay||Math.min(dateInfo().day,6)),type:TASK_TYPES[0],priority:'medium',due:'',notes:'',url:'',checklist:[]};
 modal(old?'Изменить задание':'Небольшой шаг вперёд',`<form id="task-form"><div class="form-grid"><label class="field full">Что нужно сделать?<input class="input" name="title" required maxlength="500" value="${esc(t.title)}" placeholder="Например, закончить лабораторную №4"></label><label class="field">Предмет<select class="input" name="subjectId">${subjectOptions(t.subjectId)}</select></label><label class="field">День в расписании<select class="input" name="day">${dayOptions(t.day)}</select></label><label class="field">Тип работы<select class="input" name="type">${TASK_TYPES.map(type=>`<option ${t.type===type?'selected':''}>${esc(type)}</option>`).join('')}</select></label><label class="field">Приоритет<select class="input" name="priority">${[['low','Низкий'],['medium','Средний'],['high','Высокий']].map(([v,n])=>`<option value="${v}" ${t.priority===v?'selected':''}>${n}</option>`).join('')}</select></label><label class="field">Дедлайн<input class="input" name="due" type="date" value="${esc(t.due)}"></label><label class="field">Ссылка на материалы<input class="input" name="url" type="url" maxlength="2048" value="${esc(t.url)}" placeholder="https://docs.google.com/…"></label><label class="field full">Заметки<textarea class="input" name="notes" rows="3" maxlength="20000" placeholder="Детали, которые не хочется держать в голове">${esc(t.notes)}</textarea></label><div class="field full">Чек-лист<div class="checklist-editor" id="step-list"></div><button class="text-btn" id="add-step" type="button">${icon('plus')} Добавить пункт</button></div></div><p class="form-status" role="status"></p><div class="form-actions"><button type="button" class="btn" data-action="modal-close">Отмена</button><button type="submit" class="btn primary">${old?'Сохранить изменения':'Добавить задание'}</button></div></form>`,{wide:true,onSubmit:form=>{
 const fd=new FormData(form),now=new Date().toISOString();
 const checklist=[...form.querySelectorAll('.step-editor')].map(row=>({id:row.dataset.id,text:row.querySelector('[name="stepText"]').value.trim(),done:row.querySelector('[name="stepDone"]').checked})).filter(s=>s.text);
 const task={id:old?.id||uid(),title:fd.get('title').trim(),subjectId:fd.get('subjectId'),day:Number(fd.get('day')),type:fd.get('type'),priority:fd.get('priority'),due:fd.get('due'),url:fd.get('url').trim(),notes:fd.get('notes'),done:old?.done||false,checklist,createdAt:old?.createdAt||now,updatedAt:now};
 const next=validateState({...state,tasks:old?state.tasks.map(item=>item.id===id?task:item):[...state.tasks,task]});state=next;closeModal();save(old?'Задание обновлено':'Задание добавлено');
 }});
 const list=modalRoot.querySelector('#step-list');
 const addStep=(step={id:uid(),text:'',done:false})=>{const row=document.createElement('div');row.className='step-editor';row.dataset.id=step.id;row.innerHTML=`<input class="check" type="checkbox" name="stepDone" ${step.done?'checked':''} aria-label="Пункт выполнен"><input class="input" name="stepText" maxlength="1000" value="${esc(step.text)}" placeholder="Следующий маленький шаг"><button class="icon-btn" type="button" aria-label="Удалить пункт">${icon('close')}</button>`;row.querySelector('button').onclick=()=>row.remove();list.append(row);return row;};
 t.checklist.forEach(addStep);modalRoot.querySelector('#add-step').onclick=()=>{if(list.children.length>=200){toast('В одном чек-листе до 200 пунктов.');return;}addStep().querySelector('[name="stepText"]').focus();};
}
function lessonEditor(id='',day=0){
 const old=state.schedule.find(l=>l.id===id),l=old||{subjectId:state.subjects[0]?.id||'',day:Number(day)||selectedDay||Math.min(dateInfo().day,6),start:'09:00',end:'10:20',room:'',type:'Лекция',teacher:''};
 modal(old?'Изменить пару':'Добавить пару в расписание',`<form><div class="form-grid"><label class="field full">Предмет<select class="input" name="subjectId" id="lesson-subject"><option value="new">+ Новый предмет</option>${subjectOptions(l.subjectId)}</select></label><label class="field full" id="new-subject-field">Название нового предмета<input class="input" name="newSubject" maxlength="300" placeholder="Например, Веб-программирование"></label><label class="field">День недели<select class="input" name="day">${dayOptions(l.day)}</select></label><label class="field">Тип занятия<input class="input" name="type" maxlength="120" value="${esc(l.type)}" list="lesson-types"><datalist id="lesson-types"><option>Лекция</option><option>Практика</option><option>Лабораторная</option><option>Семинар</option></datalist></label><label class="field">Начало<input class="input" name="start" type="time" value="${l.start}" required></label><label class="field">Окончание<input class="input" name="end" type="time" value="${l.end}" required></label><label class="field">Аудитория<input class="input" name="room" maxlength="160" value="${esc(l.room)}" placeholder="B–304"></label><label class="field">Преподаватель<input class="input" name="teacher" maxlength="300" value="${esc(l.teacher)}" placeholder="Имя преподавателя"></label></div><p class="form-status" role="status"></p><div class="form-actions">${old?`<button type="button" class="btn danger" id="delete-lesson">Удалить пару</button>`:''}<button type="button" class="btn" data-action="modal-close">Отмена</button><button type="submit" class="btn primary">Сохранить пару</button></div></form>`,{onSubmit:form=>{
 const fd=new FormData(form);let subjectId=fd.get('subjectId'),subjects=[...state.subjects];
 if(subjectId==='new'){const name=fd.get('newSubject').trim();if(!name)throw new Error('Укажите название предмета.');const existing=subjects.find(s=>s.name.toLowerCase()===name.toLowerCase());if(existing)subjectId=existing.id;else{subjectId=uid();subjects.push({id:subjectId,name,totalHours:null,excusedHours:0,unexcusedHours:0});}}
 const subject=subjects.find(s=>s.id===subjectId);
 const lesson={id:old?.id||uid(),subjectId,subject:subject.name,day:Number(fd.get('day')),start:fd.get('start'),end:fd.get('end'),room:fd.get('room').trim()||'Не указана',teacher:fd.get('teacher').trim()||'Не указан',type:fd.get('type').trim()||'Занятие',source:old?.source||'manual'};
 const conflict=state.schedule.find(s=>s.id!==old?.id&&s.day===lesson.day&&s.start<lesson.end&&s.end>lesson.start);
 if(conflict)throw new Error(`В это время уже есть пара «${conflict.subject}» (${conflict.start}–${conflict.end}). Уточните время.`);
 const next=validateState({...state,subjects,schedule:old?state.schedule.map(s=>s.id===id?lesson:s):[...state.schedule,lesson]});state=next;closeModal();save('Пара сохранена');
 }});
 const select=modalRoot.querySelector('#lesson-subject');if(l.subjectId)select.value=l.subjectId;
 const update=()=>{const field=modalRoot.querySelector('#new-subject-field');field.classList.toggle('hidden',select.value!=='new');field.querySelector('input').required=select.value==='new';};select.onchange=update;update();
 modalRoot.querySelector('#delete-lesson')?.addEventListener('click',()=>confirmDialog('Удалить пару?', 'Задания по этому предмету останутся в разделе «Задания».',()=>{state.schedule=state.schedule.filter(s=>s.id!==id);save('Пара удалена');},'Удалить пару'));
}
function attendanceEditor(id){
 const s=subjectFor(id);if(!s)return;
 modal('Посещаемость · '+esc(s.name),`<form><p class="modal-description">Уточните часы из учебного плана и портала HEMIS. Неизвестное общее число часов оставьте пустым.</p><div class="form-grid"><label class="field full">Общее число часов предмета<input class="input" name="totalHours" type="number" min="0" max="100000" step="0.5" value="${s.totalHours??''}" placeholder="Например, 90"><small>Для расчёта используйте ту нагрузку, по которой ваш вуз учитывает НБ.</small></label><label class="field">Уважительные пропуски, ч<input class="input" name="excusedHours" type="number" min="0" max="100000" step="0.5" value="${s.excusedHours}" required></label><label class="field">Неуважительные пропуски, ч<input class="input" name="unexcusedHours" type="number" min="0" max="100000" step="0.5" value="${s.unexcusedHours}" required></label></div><p class="form-status" role="status"></p><div class="form-actions"><button class="btn" type="button" data-action="modal-close">Отмена</button><button class="btn primary" type="submit">Сохранить</button></div></form>`,{onSubmit:form=>{const fd=new FormData(form);state=validateState({...state,subjects:state.subjects.map(item=>item.id===id?{...item,totalHours:fd.get('totalHours')===''?null:Number(fd.get('totalHours')),excusedHours:Number(fd.get('excusedHours')),unexcusedHours:Number(fd.get('unexcusedHours'))}:item)});closeModal();save('Посещаемость обновлена');}});
}
function connectionDialog(){
 let authMode='login',ready=false,requiresKey=false,probeSeq=0;
 modal('Подключить HEMIS',`<form class="connection-form"><div class="connection-guide"><label class="field">Способ подключения<select class="input" name="transport" id="connection-transport"><option value="cloud" ${connectionConfig.transport==='cloud'?'selected':''}>HTTPS-мост · для GitHub и телефона</option><option value="local" ${connectionConfig.transport==='local'?'selected':''}>Локальный мост · Windows</option><option value="direct" ${connectionConfig.transport==='direct'?'selected':''}>Прямой запрос · если вуз разрешает</option></select></label><div id="cloud-settings"><label class="field" style="margin-top:14px">Адрес вашего HTTPS-моста<input class="input" name="bridgeUrl" type="url" maxlength="2048" value="${esc(connectionConfig.bridgeUrl)}" placeholder="https://hemis-bridge.example.workers.dev" autocomplete="off"></label><label class="field" style="margin-top:14px">Ключ HTTPS-моста<input class="input" name="bridgeKey" type="password" maxlength="256" value="${esc(connectionKey)}" autocomplete="off" placeholder="Ключ, заданный владельцем сервера"><small>Это отдельный ключ сервера. Не пароль HEMIS. В браузере он хранится только до закрытия приложения.</small></label><p class="bridge-setup-note" id="cloud-intro">Сервер ещё не создан? <a href="./bridge-setup.html" target="_blank" rel="noopener noreferrer">Открыть пошаговую настройку →</a></p><p>Мост получает данные входа для передачи в HEMIS. Указывайте только свой сервер или сервер, владельцу которого доверяете.</p></div><div id="local-settings"><p>Запустите start.bat из папки Planner на этом компьютере. Если браузер блокирует localhost, входите в локальной версии.</p><a class="btn" href="http://127.0.0.1:8080/#connection" target="_blank" rel="noopener noreferrer">Открыть локальную версию ${icon('external')}</a></div><div id="direct-settings"><p>Прямое подключение работает только если сервер вуза разрешает CORS. При сетевой ошибке выберите HTTPS-мост или локальный мост.</p></div><div class="settings-inline" style="margin-top:14px"><button type="button" class="btn" id="test-connection">${icon('wifi')} Проверить подключение</button><span class="badge" id="connection-ready">Не проверено</span></div><p class="form-status" id="bridge-status" role="status"></p></div><div class="modal-tabs"><button type="button" class="active" data-auth-mode="login">Логин и пароль</button><button type="button" data-auth-mode="token">Bearer-токен</button></div><div class="form-grid"><label class="field full">Ваш университет<select name="university" class="input" id="university">${UNIVERSITIES.map((u,i)=>`<option value="${i}">${esc(u.name)} · ${esc(new URL(u.url).hostname)}</option>`).join('')}<option value="custom">Другой вуз · свой URL</option></select></label><label class="field full hidden" id="custom-url-field">Адрес студенческого портала<input class="input" name="url" type="url" placeholder="https://student.example.uz"></label><label class="field auth-login">ID студента / логин<input class="input" name="login" autocomplete="username" required maxlength="160"></label><label class="field auth-login">Пароль HEMIS<input class="input" name="password" type="password" autocomplete="current-password" required maxlength="256"></label><label class="field full hidden auth-token">Готовый Bearer-токен<textarea class="input" name="token" rows="3" autocomplete="off" spellcheck="false" placeholder="eyJ…"></textarea></label><label class="checkbox-label field full hidden" id="public-proxy-field"><input type="checkbox" name="publicProxy"><span>Разрешить публичные прокси для загрузки данных по токену<small>Прокси получат Bearer-токен. Пароль HEMIS через них не передаётся.</small></span></label></div><p class="form-status" id="connection-status" role="status"></p><div class="connection-recovery hidden" id="connection-help"></div><div class="form-actions"><button type="button" class="btn" data-action="modal-close">Отмена</button><button class="btn primary" type="submit" disabled>Загрузить мою неделю ${icon('arrow')}</button></div></form>`,{wide:true,onSubmit:async form=>{
 const fd=new FormData(form),status=form.querySelector('#connection-status'),button=form.querySelector('[type="submit"]'),transport=fd.get('transport');
 button.disabled=true;status.classList.remove('error');form.querySelector('#connection-help').classList.add('hidden');
 try{
 if(!ready)throw new Error('Сначала проверьте подключение к мосту.');
 const bridgeUrl=transport==='cloud'?normalizeHttpsBridge(fd.get('bridgeUrl')):'';
 if(transport==='cloud'&&!bridgeUrl)throw new Error('Сначала создайте HTTPS-мост по инструкции и укажите его адрес.');
 connectionConfig=saveConnectionSettings({transport,bridgeUrl:bridgeUrl||connectionConfig.bridgeUrl});connectionKey=String(fd.get('bridgeKey')||'');
 const selected=fd.get('university'),baseUrl=selected==='custom'?fd.get('url'):UNIVERSITIES[Number(selected)].url;
 const client=new HemisClient({baseUrl,token:authMode==='token'?fd.get('token'):'',allowPublicProxy:transport==='direct'&&fd.has('publicProxy'),transport,bridgeUrl,bridgeKey:connectionKey,onStatus:message=>{status.textContent=message;}});
 if(authMode==='login')await client.login(fd.get('login'),fd.get('password'));
 const data=await client.load();
 form.querySelector('[name="password"]').value='';form.querySelector('[name="token"]').value='';
 const university=selected==='custom'?new URL(client.baseUrl).hostname:UNIVERSITIES[Number(selected)].name;
 applyHemis(data,university);hemis=client;closeModal();navigate('schedule');toast('Расписание и посещаемость загружены');showImportWarnings(data.warnings);
 }catch(error){
   const help=form.querySelector('#connection-help');
   if(error.code==='CONNECTION_UNAVAILABLE'||error.code==='CLOUD_BRIDGE_NOT_CONFIGURED'){
     help.classList.remove('hidden');help.innerHTML=transport==='cloud'?'<strong>HTTPS-мост ещё не доступен</strong><p>Проверьте, что Worker опубликован, а в нём настроены BRIDGE_KEY и ALLOWED_ORIGINS. Простая загрузка worker.js на GitHub не запускает сервер.</p><a href="./bridge-setup.html" target="_blank" rel="noopener noreferrer">Открыть инструкцию настройки →</a>':'<strong>Нужен рабочий маршрут подключения</strong><p>Для Windows запустите start.bat и откройте локальную версию. Для GitHub и телефона настройте HTTPS-мост. Прямой запрос не может изменить CORS сервера вуза.</p>';
   }else if(error.code==='UPSTREAM_NOT_JSON'){
     help.classList.remove('hidden');help.innerHTML=`<strong>Портал вуза отклонил запрос через этот маршрут (HTTP ${esc(error.status||451)})</strong><p>Мост исправен, но портал HEMIS вернул HTML-страницу вместо данных API (многие вузы в Узбекистане блокируют зарубежные облачные IP Cloudflare по Geo-IP / TAS-IX). На компьютере в местной сети выберите «Локальный мост · Windows», загрузите расписание и перенесите его на телефон через «Синхронизация».</p>${transport==='cloud'?'<button type="button" class="btn" id="switch-local-bridge" style="margin-top:8px">Переключить на локальный мост Windows</button>':''}`;
     help.querySelector('#switch-local-bridge')?.addEventListener('click',()=>{const select=form.querySelector('[name="transport"]');select.value='local';select.dispatchEvent(new Event('change'));});
   }
   throw error;
 }finally{button.disabled=false;}
 }});
 const form=modalRoot.querySelector('form'),transport=form.querySelector('[name="transport"]'),bridgeUrl=form.querySelector('[name="bridgeUrl"]'),bridgeKey=form.querySelector('[name="bridgeKey"]'),status=form.querySelector('#bridge-status'),badge=form.querySelector('#connection-ready'),test=form.querySelector('#test-connection');
 function enable(){bridgeKey.required=requiresKey;bridgeKey.minLength=requiresKey?24:0;const allowed=ready&&(!requiresKey||bridgeKey.value.trim().length>=24);form.querySelectorAll('[name="login"],[name="password"],[name="token"]').forEach(input=>input.disabled=!allowed);form.querySelector('[type="submit"]').disabled=!allowed;badge.textContent=allowed?'Можно входить':ready&&requiresKey?'Введите ключ моста':'Не настроено';badge.className='badge '+(allowed?'ok':'');}
 async function runProbe(seq=++probeSeq){test.disabled=true;status.classList.remove('error');status.textContent='Проверяем доступность…';try{if(transport.value==='direct'){ready=true;requiresKey=false;status.textContent='Прямой режим не использует мост. Проверка авторизации выполняется после отправки формы.';return;}const remote=transport.value==='cloud';const url=remote?normalizeHttpsBridge(bridgeUrl.value):'';if(remote&&!url)throw new Error('Укажите адрес опубликованного HTTPS-моста. Начните с пошаговой инструкции.');const result=await probeBridge({bridgeUrl:url});if(seq!==probeSeq)return;ready=result.ok;requiresKey=remote&&Boolean(result.requiresKey);status.textContent=result.message;status.classList.toggle('error',!result.ok);if(result.ok)connectionConfig=saveConnectionSettings({transport:transport.value,bridgeUrl:url||connectionConfig.bridgeUrl});}catch(error){if(seq!==probeSeq)return;ready=false;status.textContent=error.message;status.classList.add('error');}finally{if(seq===probeSeq){test.disabled=false;enable();}}}
 function syncMode(){const seq=++probeSeq,cloudMode=transport.value==='cloud',localMode=transport.value==='local';ready=transport.value==='direct';requiresKey=cloudMode;form.querySelector('#cloud-settings').classList.toggle('hidden',!cloudMode);form.querySelector('#local-settings').classList.toggle('hidden',!localMode);form.querySelector('#direct-settings').classList.toggle('hidden',transport.value!=='direct');bridgeUrl.required=cloudMode;bridgeKey.required=cloudMode;bridgeKey.minLength=cloudMode?24:0;form.querySelector('#public-proxy-field').classList.toggle('hidden',transport.value!=='direct'||authMode!=='token');status.classList.remove('error');status.textContent=cloudMode&&!bridgeUrl.value?'Для входа с GitHub сначала создайте HTTPS-мост по инструкции.':ready?'Прямой режим выбран. Разрешение CORS зависит от вуза.':'Нажмите «Проверить подключение». Проверка не отправляет логин и пароль.';enable();if(localMode||(cloudMode&&bridgeUrl.value.trim()))runProbe(seq);}
 test.onclick=()=>runProbe();
 transport.onchange=syncMode;bridgeUrl.oninput=()=>{probeSeq++;ready=false;status.classList.remove('error');status.textContent=bridgeUrl.value?'Адрес изменён. Проверьте подключение.':'Сначала создайте HTTPS-мост по пошаговой инструкции.';enable();};bridgeKey.oninput=()=>{connectionKey=bridgeKey.value;enable();};
 const university=form.querySelector('#university');university.onchange=()=>{const custom=university.value==='custom';form.querySelector('#custom-url-field').classList.toggle('hidden',!custom);form.querySelector('[name="url"]').required=custom;};
 modalRoot.querySelectorAll('[data-auth-mode]').forEach(button=>button.onclick=()=>{authMode=button.dataset.authMode;modalRoot.querySelectorAll('[data-auth-mode]').forEach(b=>b.classList.toggle('active',b===button));modalRoot.querySelectorAll('.auth-login').forEach(el=>{el.classList.toggle('hidden',authMode!=='login');el.querySelector('input').required=authMode==='login';});modalRoot.querySelector('.auth-token').classList.toggle('hidden',authMode!=='token');form.querySelector('[name="token"]').required=authMode==='token';form.querySelector('#public-proxy-field').classList.toggle('hidden',transport.value!=='direct'||authMode!=='token');});
 syncMode();
}

function applyHemis(data,university='HEMIS · импорт'){
 const base=state.mode==='demo'?createEmptyState():state;
 const subjects=[...data.subjects],map=new Map(subjects.map(s=>[s.id,s]));
 // Keep local assignments and manually entered subjects when refreshing the portal.
 const aliases=new Map(subjects.map(s=>[s.name.trim().toLowerCase(),s.id]));
 const tasks=base.tasks.map(t=>{const old=base.subjects.find(s=>s.id===t.subjectId);const id=map.has(t.subjectId)?t.subjectId:aliases.get(old?.name.trim().toLowerCase());if(id)return {...t,subjectId:id};if(old&&!map.has(old.id)){subjects.push(old);map.set(old.id,old);}return t;});
 const manual=base.schedule.filter(l=>l.source==='manual').map(l=>{const matched=map.has(l.subjectId)?l.subjectId:aliases.get(l.subject.trim().toLowerCase());if(matched)return {...l,subjectId:matched,subject:map.get(matched).name};const old=base.subjects.find(s=>s.id===l.subjectId);if(old&&!map.has(old.id)){subjects.push(old);map.set(old.id,old);}return l;});
 state=validateState({...base,mode:'hemis',profile:{...base.profile,university},subjects,schedule:[...data.schedule,...manual],tasks});save();
}
function showImportWarnings(warnings=[]){if(!warnings.length)return;modal('Проверьте загруженные данные',`<p class="modal-description">${warnings.map(esc).join('<br><br>')}</p><div class="form-actions"><button class="btn primary" data-action="modal-close">Понятно</button></div>`);}
function rawImport(){modal('Импорт ответа HEMIS',`<form><p class="modal-description">Вставьте массив пар или объект {schedule, subjects, attendance}. Поддерживаются вложенные ответы {data: {items: […]}}. Пароли и токены в JSON не нужны.</p><label class="field">Сырой JSON<textarea class="input mono" name="raw" rows="10" required spellcheck="false" maxlength="2000000" placeholder='{"schedule": […], "subjects": […], "attendance": […]}'></textarea></label><p class="form-status" role="status"></p><div class="form-actions"><button type="button" class="btn" data-action="modal-close">Отмена</button><button class="btn primary" type="submit">Импортировать</button></div></form>`,{wide:true,onSubmit:form=>{const data=importHemisData(new FormData(form).get('raw'));applyHemis(data);closeModal();navigate('schedule');toast(`Импортировано: ${pairText(data.schedule.length)}, ${data.subjects.length} предметов`);showImportWarnings(data.warnings);}});}
function exportBackup(){const safe=validateState(state),blob=new Blob([JSON.stringify(safe,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`hemis-planner-${localDate()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Резервная копия сохранена в JSON');}
function importBackup(){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{const file=input.files[0];if(!file)return;try{if(file.size>4*1024*1024)throw new Error('Выберите JSON-копию до 4 МБ.');const next=validateState(JSON.parse(await file.text()));confirmDialog('Восстановить резервную копию?',`${file.name}: ${pairText(next.schedule.length)}, ${taskText(next.tasks.length)}, ${next.subjects.length} предметов. Текущие данные на устройстве заменятся. Сначала экспортируйте их, если они нужны.`,()=>{state=next;hemis=null;save();navigate('schedule');toast('Резервная копия восстановлена');},'Восстановить');}catch(error){toast(error.message);}};input.click();}
async function cloudAction(direction){
 if(!cloud||syncBusy)return;syncBusy=true;syncMessage=direction==='push'?'Шифруем и отправляем…':'Ищем зашифрованную копию…';render();
 try{
 if(direction==='push'){if(pendingRemote)throw new Error('Найдена облачная копия, которую вы ещё не применили. Экспортируйте локальный JSON и загрузите облачную копию перед отправкой.');await cloud.push(validateState(state));syncMessage='Изменения отправлены. Откройте этот же сеанс на втором устройстве и нажмите «Загрузить из облака».';toast('Зашифрованная копия отправлена');}
 else{const remote=await cloud.pull();if(!remote){syncMessage='В этом канале пока нет доступной копии. Отправьте данные с первого устройства или проверьте ID и пароль.';}
 else{pendingRemote=true;const next=validateState(remote);syncMessage=`Найдена копия от ${new Date(next.updatedAt).toLocaleString('ru-RU',{timeZone:'Asia/Tashkent'})}.`;confirmDialog('Загрузить облачную копию?',`${pairText(next.schedule.length)}, ${taskText(next.tasks.length)}. Копия заменит локальные данные. Экспортируйте текущие данные, если хотите сохранить обе версии.`,()=>{state=next;pendingRemote=false;hemis=null;save();syncMessage='Облачная копия загружена на устройство.';render();toast('Данные загружены');},'Загрузить копию');}}
 }catch(error){syncMessage=error.message;toast(error.code==='CONFLICT'?'В облаке другая версия. Сохраните локальный JSON и загрузите облачную копию.':error.message);}finally{syncBusy=false;render();}
}
function installDialog(){if(installPrompt){installPrompt.prompt();installPrompt.userChoice.then(()=>{installPrompt=null;});return;}modal('Planner всегда под рукой',`<p class="modal-description">Откройте приложение по HTTPS или адресу localhost.</p><div class="notice"><strong>Android / Chrome:</strong> меню ⋮ → «Установить приложение» или «Добавить на главный экран».<br><br><strong>iPhone / iPad / Safari:</strong> «Поделиться» → «На экран Домой».<br><br><strong>На компьютере:</strong> значок установки справа в адресной строке Chrome или Edge. Если приложение уже установлено, откройте его из списка приложений.</div><div class="form-actions"><button class="btn primary" data-action="modal-close">Понятно</button></div>`);}
function searchDialog(){modal('Найти нужное',`<label class="search-field" style="width:100%;display:block"><span>${icon('search')}</span><input class="input" id="global-search" type="search" placeholder="Предмет или задание…" autocomplete="off" aria-label="Быстрый поиск"></label><div class="search-results" id="search-results" style="margin-top:18px"></div>`);const input=modalRoot.querySelector('#global-search'),results=modalRoot.querySelector('#search-results');const search=()=>{const q=input.value.toLowerCase().trim();if(!q){results.innerHTML='<p class="modal-description">Начните вводить название предмета или задания.</p>';return;}const tasks=state.tasks.filter(t=>t.title.toLowerCase().includes(q)).slice(0,6),subjects=state.subjects.filter(s=>s.name.toLowerCase().includes(q)).slice(0,5);results.innerHTML=tasks.map(t=>`<button class="search-result" data-action="search-task" data-id="${esc(t.id)}"><span>${esc(t.title)}</span><small>Задание</small></button>`).join('')+subjects.map(s=>`<button class="search-result" data-action="search-subject" data-id="${esc(s.id)}"><span>${esc(s.name)}</span><small>Предмет</small></button>`).join('')||'<p class="modal-description">Ничего не найдено.</p>';};input.oninput=search;search();}
async function sendReminder(test=false){
 if(!('Notification' in window))throw new Error('Этот браузер не поддерживает уведомления. На iPhone установите PWA на экран «Домой».');
 let permission=Notification.permission;if(permission==='default'&&test)permission=await Notification.requestPermission();if(permission!=='granted')throw new Error('Разрешите уведомления для этого сайта в настройках браузера.');
 const summary=summaries(state),due=state.tasks.filter(t=>!t.done&&(t.due?t.due===tomorrowDate():t.day===dateInfo().day%7+1));
 const body=`Завтра ${pairText(summary.tomorrow.lessons)}. ${due.length?`К сдаче: ${due.slice(0,4).map(t=>t.title).join('; ')}${due.length>4?' и другие':''}.`:'Заданий к сдаче нет.'}`;
 const options={body,icon:new URL('./icon-192.png',location.href).href,tag:test?'hemis-test':'hemis-evening-'+localDate()};
 const registration=notificationRegistration||await navigator.serviceWorker?.getRegistration();
 if(registration)await registration.showNotification(test?'HEMIS Planner · проверка':'Завтра начинается сегодня',options);else new Notification('HEMIS Planner',options);
}
async function minuteTick(){
 if(!modalRoot.firstChild&&route==='schedule')render();
 if(!state.settings.notificationEnabled)return;
 const now=dateInfo();let already;
 try{already=localStorage.getItem(STORE+'-reminder');}catch{return;}
 if(now.time>=state.settings.notificationTime&&already!==now.date){try{await sendReminder();localStorage.setItem(STORE+'-reminder',now.date);}catch{/* A denied/background notification is retried only on the next tick. */}}
}

document.addEventListener('click',async event=>{
 const target=event.target.closest('button,[data-action]');if(!target)return;
 if(target.dataset.nav){closeModal();navigate(target.dataset.nav);return;}
 if(target.dataset.day!==undefined&&!target.dataset.action){selectedDay=Number(target.dataset.day);render();return;}
 const action=target.dataset.action,id=target.dataset.id;
 try{switch(action){
 case'menu':sidebarOpen=!sidebarOpen;render();break;case'menu-close':sidebarOpen=false;render();break;case'modal-close':closeModal();break;
 case'theme-toggle':state.settings.theme=document.documentElement.dataset.theme==='dark'?'light':'dark';save('Тема оформления сохранена');break;
 case'bridge-check':{target.disabled=true;const status=modalRoot.querySelector('#bridge-status')||document.querySelector('#bridge-status');try{const result=await probeBridge();if(status){status.textContent=result.message;status.classList.toggle('error',!result.ok);}}finally{target.disabled=false;}}break;
 case'task-new':taskEditor('',target.dataset.subject,Number(target.dataset.day));break;case'task-edit':taskEditor(id);break;
 case'task-expand':expanded.has(id)?expanded.delete(id):expanded.add(id);render();break;
 case'task-delete':confirmDialog('Удалить задание?','Задание и его чек-лист будут удалены с этого устройства.',()=>{state.tasks=state.tasks.filter(t=>t.id!==id);expanded.delete(id);save('Задание удалено');},'Удалить');break;
 case'lesson-new':lessonEditor('',Number(target.dataset.day));break;case'lesson-edit':lessonEditor(id);break;case'attendance-edit':attendanceEditor(id);break;
 case'connect':connectionDialog();break;case'raw-import':rawImport();break;
 case'hemis-refresh':if(!hemis){connectionDialog();break;}target.disabled=true;try{const data=await hemis.load();applyHemis(data,state.profile.university);toast('Данные HEMIS обновлены');showImportWarnings(data.warnings);}finally{target.disabled=false;}break;
 case'demo':if(state.mode==='demo'){try{localStorage.setItem(STORE+'-legacy','1');}catch{}state=createDemoState();save();navigate('schedule');toast('Демо-расписание готово');}else confirmDialog('Открыть демо?','Демо-данные заменят текущее пространство. Экспортируйте JSON, если хотите его сохранить.',()=>{try{localStorage.setItem(STORE+'-legacy','1');}catch{}state=createDemoState();hemis=null;save();navigate('schedule');},'Открыть демо');break;
 case'empty':confirmDialog('Начать с чистого листа?','Расписание, задания и статистика на устройстве будут очищены. Сохраните JSON-копию, если они нужны.',()=>{try{localStorage.setItem(STORE+'-legacy','1');}catch{}state=createEmptyState();hemis=null;save();navigate('schedule');},'Создать пространство');break;
 case'export':exportBackup();break;case'backup-import':importBackup();break;
 case'sync-push':await cloudAction('push');break;case'sync-pull':await cloudAction('pull');break;case'sync-disconnect':cloud?.disconnect();cloud=null;pendingRemote=false;syncMessage='Сеанс закрыт. Локальные данные сохранены.';render();break;
 case'install':installDialog();break;case'search':searchDialog();break;
 case'search-task':closeModal();taskEditor(id);break;case'search-subject':closeModal();selectedDay=state.schedule.find(l=>l.subjectId===id)?.day||0;navigate('schedule');break;
 case'notification-test':await sendReminder(true);toast('Проверочное уведомление отправлено');break;
 }}catch(error){toast(error.message);}
});
document.addEventListener('change',event=>{
 const input=event.target;
 if(input.dataset.taskToggle){const task=state.tasks.find(t=>t.id===input.dataset.taskToggle);if(task){task.done=input.checked;task.updatedAt=new Date().toISOString();save(task.done?'Ещё одно дело готово ✓':'Задание возвращено в работу');}}
 if(input.dataset.stepToggle){const task=state.tasks.find(t=>t.id===input.dataset.task);const step=task?.checklist.find(s=>s.id===input.dataset.stepToggle);if(step){step.done=input.checked;task.updatedAt=new Date().toISOString();save();}}
 if(input.id==='task-filter'){taskFilter=input.value;render();}
 if(input.id==='theme-select'){state.settings.theme=input.value;save('Тема оформления сохранена');}
});
document.addEventListener('input',event=>{if(event.target.id==='task-search'){const input=event.target,pos=input.selectionStart;taskQuery=input.value;render();const next=document.querySelector('#task-search');next.focus();try{next.setSelectionRange(pos,pos);}catch{}}});
document.addEventListener('submit',async event=>{
 const form=event.target;if(!['profile-form','notification-form','sync-form'].includes(form.id))return;event.preventDefault();const fd=new FormData(form);
 try{
 if(form.id==='profile-form'){state.profile={name:fd.get('name').trim(),university:fd.get('university').trim(),group:fd.get('group').trim()};save('Профиль сохранён');}
 if(form.id==='notification-form'){const enabled=fd.has('enabled');if(enabled){if(!('Notification' in window))throw new Error('Уведомления не поддерживаются этим браузером.');let permission=Notification.permission;if(permission==='default')permission=await Notification.requestPermission();if(permission!=='granted')throw new Error('Разрешите уведомления для этого сайта в настройках браузера.');}state.settings.notificationEnabled=enabled;state.settings.notificationTime=fd.get('time');save('Настройки напоминания сохранены');}
 if(form.id==='sync-form'){const button=form.querySelector('button');button.disabled=true;const password=fd.get('password');form.querySelector('[name="password"]').value='';cloud=new CloudSync({studentId:fd.get('studentId'),password,onStatus:status=>{syncMessage=status.message||'';const el=document.querySelector('#sync-status');if(el)el.textContent=syncMessage;}});try{await cloud.connect();syncMessage='Защищённый сеанс создан. Если на другом устройстве уже есть копия — сначала загрузите её.';render();}catch(error){cloud?.disconnect();cloud=null;button.disabled=false;throw error;}}
 }catch(error){toast(error.message);}
});
document.addEventListener('keydown',event=>{if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k'){event.preventDefault();searchDialog();}if(event.key.toLowerCase()==='n'&&!event.ctrlKey&&!event.metaKey&&!modalRoot.firstChild&&!/INPUT|TEXTAREA|SELECT/.test(document.activeElement.tagName)){event.preventDefault();taskEditor();}});
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(['schedule','tasks','attendance','sync','settings','connection'].includes(next)&&next!==route){route=next;sidebarOpen=false;render();}});
window.addEventListener('online',()=>{render();toast('Вы снова онлайн');});window.addEventListener('offline',()=>render());
window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();installPrompt=event;});
window.addEventListener('appinstalled',()=>{installPrompt=null;toast('HEMIS Planner установлен');});
window.matchMedia('(prefers-color-scheme: dark)').addEventListener('change',()=>{if(state.settings.theme==='system')render();});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')minuteTick();});
if('serviceWorker' in navigator&&location.protocol!=='file:'){
 navigator.serviceWorker.register('./sw.js',{scope:'./',updateViaCache:'none'}).then(reg=>{notificationRegistration=reg;if(reg.waiting)toast('Доступно обновление. Закройте вкладки Planner и откройте снова.');}).catch(()=>toast('Офлайн-режим пока недоступен. Проверьте загрузку файлов приложения.'));
}
render();setInterval(minuteTick,60000);if(storageError)setTimeout(()=>toast(storageError),500);
if(location.protocol==='file:')setTimeout(()=>toast('Запустите start.bat или откройте сайт по HTTPS. Модули и PWA не работают через file://.'),1000);
